<?php
namespace App\Http\Controllers\Admin;
use App\Enums\ShipmentStatus; use App\Http\Controllers\Controller; use App\Models\Customer; use App\Models\Shipment; use App\Notifications\ShipmentStatusUpdated; use App\Services\ShipmentService; use App\Services\ShipmentStatusService; use Carbon\Carbon; use Illuminate\Http\Request; use InvalidArgumentException;
class ShipmentController extends Controller {public function index(Request $request){$allowed=['created_at','tracking_number','destination','status','estimated_delivery'];$sort=in_array($request->input('sort'),$allowed,true)?$request->input('sort'):'created_at';$direction=$request->input('direction')==='asc'?'asc':'desc';$shipments=Shipment::with('customer')->when($request->filled('search'),function($q)use($request){$s=trim($request->input('search'));$q->where(function($q)use($s){$q->where('tracking_number','like',"%$s%")->orWhere('origin','like',"%$s%")->orWhere('destination','like',"%$s%")->orWhereHas('customer',fn($c)=>$c->where('name','like',"%$s%"));});})->when($request->filled('status'),function($q)use($request){if($s=ShipmentStatus::tryFrom($request->input('status'))) $q->where('status',$s->value);})->orderBy($sort,$direction)->paginate(20)->withQueryString();return view('admin.shipments.index',compact('shipments'));}public function create(){return view('admin.shipments.create',['customers'=>Customer::orderBy('name')->get()]);}public function store(Request $request){$v=$request->validate(['customer_id'=>['required','integer','exists:customers,id'],'origin'=>['required','string','max:255'],'destination'=>['required','string','max:255'],'current_location'=>['nullable','string','max:255'],'estimated_delivery'=>['nullable','date_format:Y-m-d\\TH:i']]);$eta=!empty($v['estimated_delivery'])?Carbon::createFromFormat('Y-m-d\\TH:i',$v['estimated_delivery'],config('app.display_timezone'))->utc():null;$shipment=app(ShipmentService::class)->create(Customer::findOrFail($v['customer_id']),$v['origin'],$v['destination'],$v['current_location']??null,$eta,$request->user()->id);return redirect()->route('admin.shipments.show',$shipment)->with('success','Shipment created successfully.');}public function show(Shipment $shipment){$shipment->load(['customer','events.creator']);$allowedStatuses=app(ShipmentStatusService::class)->allowedTransitions($shipment);return view('admin.shipments.show',compact('shipment','allowedStatuses'));}public function updateStatus(Request $request,Shipment $shipment){$v=$request->validate(['status'=>['required','string'],'location'=>['nullable','string','max:255'],'description'=>['nullable','string','max:1000']]);$new=ShipmentStatus::tryFrom($v['status']);if(!$new)return back()->withErrors(['status'=>'Invalid shipment status.']);try{$shipment=app(ShipmentStatusService::class)->changeStatus($shipment,$new,$v['location']??null,$v['description']??null,$request);}catch(InvalidArgumentException $e){return back()->withErrors(['status'=>$e->getMessage()]);}$customer=$shipment->customer;if($customer?->email&&$customer->notifications_enabled)$customer->notify(new ShipmentStatusUpdated($shipment));return redirect()->route('admin.shipments.show',$shipment)->with('success','Shipment status updated successfully.');}}
